import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 2 - web | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"web/page/2","tag":"web","title":"Page 2 - web | Tag","prev":"/tags/web/","next":"/tags/web/page/3/","posts":[{"title":"拖拽排序列表","url":"/posts/2023-04-16-draggable-list/","date":"2023-04-16 12:31","tags":["web"],"html":"<p>拖拽排序是一个很常见的功能，在浏览器不支持原生拖拽功能的时代，人们只能使用鼠标的点击事件来模拟拖拽效果，手动控制拖拽元素的位置来进行移动操作。随着原生拖拽 API 的支持，在实现这个功能的时候就可以更简单一点了。</p>\\n<h2 id=\\"相关事件\\" tabindex=\\"-1\\">相关事件 <a class=\\"header-anchor\\" href=\\"#相关事件\\" aria-label=\\"Permalink to &quot;相关事件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先，你要想拖拽某个元素的话必须设置属性 <code>draggable=&quot;true&quot;</code> 才可以进行拖拽操作。然后进行拖拽操作主要有以下事件需要处理。</p>\\n<ol>\\n<li>onDragStart 当拖拽开始的时候触发</li>\\n<li>onDragOver 当拖拽到某个元素内部的时候触发</li>\\n<li>onDragEnter 当拖拽进入某个元素的时候触发</li>\\n<li>onDragEnd 当鼠标松开，拖拽结束的时候触发</li>\\n<li>onDrop 当拖拽到某个元素并松开鼠标的时候触发</li>\\n</ol>\\n<p>由于我们使用拖拽进行排序，而不是拖拽元素放到别的元素里面，所以我们并不需要进行 drop 处理，当 dragOver 某个元素的时候也不需要额外的处理。所以这两个事件的代码最简单，我们只需要移除默认的事件响应。</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragOverHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">((</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">DragEvent</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.</span><span style=\\"color:#6F42C1\\">preventDefault</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.dataTransfer.dropEffect </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'move'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, []);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dropHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">((</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">DragEvent</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.</span><span style=\\"color:#6F42C1\\">stopPropagation</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.</span><span style=\\"color:#6F42C1\\">preventDefault</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, []);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>dropEffect 有四种，默认的是 <code>copy</code> 我们需要改成 <code>move</code> 才符合需求。接下来再来看看其他三个事件：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragStartHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  (</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">DragEvent</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>, </span><span style=\\"color:#E36209\\">index</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    event.dataTransfer.effectAllowed </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'move'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">    // set dataTransfer enable mobile drag</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    event.dataTransfer.</span><span style=\\"color:#6F42C1\\">setData</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'text/plain'</span><span style=\\"color:#24292E\\">, index.</span><span style=\\"color:#6F42C1\\">toString</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    dragItem.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> index;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    copyData.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">(sortedData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    recordRect</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    onDragStart</span><span style=\\"color:#24292E\\">?.();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  [sortedData, recordRect, onDragStart]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragEnterHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  (</span><span style=\\"color:#E36209\\">index</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (dragItem.current </span><span style=\\"color:#D73A49\\">!==</span><span style=\\"color:#24292E\\"> index </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> dragOverItem.current </span><span style=\\"color:#D73A49\\">!==</span><span style=\\"color:#24292E\\"> index) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      dragOverItem.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> index;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> newData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">(copyData.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> dragData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> newData[dragItem.current];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      newData.</span><span style=\\"color:#6F42C1\\">splice</span><span style=\\"color:#24292E\\">(dragItem.current, </span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      newData.</span><span style=\\"color:#6F42C1\\">splice</span><span style=\\"color:#24292E\\">(dragOverItem.current, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">, dragData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      setSortedData</span><span style=\\"color:#24292E\\">(newData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      onDragEnter</span><span style=\\"color:#24292E\\">?.();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  [onDragEnter]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragEndHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  updateData</span><span style=\\"color:#24292E\\">?.(sortedData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  onDragEnd</span><span style=\\"color:#24292E\\">?.();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, [sortedData, updateData, onDragEnd]);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br></div></div><ol>\\n<li>dragStart 的时候记录下当前的 index，并复制一份数组数据。</li>\\n<li>dragEnter 的时候记录下拖拽进入的元素 index，然后重新排序数组会渲染一个新的列表</li>\\n<li>dragEnd 的时候同步数据到上层，展示排序后的结果</li>\\n</ol>\\n<p>完整的代码请看文章最后的链接。</p>\\n<h2 id=\\"flip-动画\\" tabindex=\\"-1\\">FLIP 动画 <a class=\\"header-anchor\\" href=\\"#flip-动画\\" aria-label=\\"Permalink to &quot;FLIP 动画&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当进行拖拽排序的时候，我们想要加上元素移动的动画，可以更明显的感受到顺序的变化。 我们使用 FLIP 技术来完成这个效果。</p>\\n<ol>\\n<li>First: 记录当前元素的位置</li>\\n<li>Last: 记录更新后元素的位置</li>\\n<li>Invert: 计算元素在 X 方向和 Y 方向的偏移，然后使用 transform 进行移动</li>\\n<li>Play: 播放 transform 动画</li>\\n</ol>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (draggable </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> containerRef?.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    Array.</span><span style=\\"color:#6F42C1\\">from</span><span style=\\"color:#24292E\\">(containerRef.current.</span><span style=\\"color:#6F42C1\\">querySelectorAll</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'[data-id]'</span><span style=\\"color:#24292E\\">)).</span><span style=\\"color:#6F42C1\\">forEach</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      async</span><span style=\\"color:#E36209\\"> node</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> dom</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> node </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#6F42C1\\"> HTMLElement</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> key</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> dom.dataset.id </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> prevRect</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> prevRects.current[key];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (key) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          const</span><span style=\\"color:#005CC5\\"> rect</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> dom.</span><span style=\\"color:#6F42C1\\">getBoundingClientRect</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          if</span><span style=\\"color:#24292E\\"> (prevRect) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            const</span><span style=\\"color:#005CC5\\"> dy</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> prevRect.y </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> rect.y;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            const</span><span style=\\"color:#005CC5\\"> dx</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> prevRect.x </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> rect.x;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dom.style.pointerEvents </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'none'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dom.</span><span style=\\"color:#6F42C1\\">animate</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              [</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                  transform: </span><span style=\\"color:#032F62\\">\`translate(\${</span><span style=\\"color:#24292E\\">dx</span><span style=\\"color:#032F62\\">}px, \${</span><span style=\\"color:#24292E\\">dy</span><span style=\\"color:#032F62\\">}px)\`</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                { transform: </span><span style=\\"color:#032F62\\">'translate(0, 0)'</span><span style=\\"color:#24292E\\"> }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              ],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                duration: </span><span style=\\"color:#005CC5\\">TIMEOUT</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                easing: </span><span style=\\"color:#032F62\\">'linear'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            await</span><span style=\\"color:#005CC5\\"> Promise</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">allSettled</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              node.</span><span style=\\"color:#6F42C1\\">getAnimations</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">animation</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> animation.finished)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dom.style.pointerEvents </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          prevRects.current[key] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> rect;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, [draggable, sortedData, containerRef]);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br></div></div><p>上面是示例代码，注意这里的 FLIP 动画加了一些特殊处理，我们使用 <code>pointerEvents</code> 禁用动画过程中的事件响应，因为动画过程中触发任何 drag 事件会导致 index 顺序被改动，然后无限进行排序操作。\\n这不是我们期望的结果，然后在动画结束的时候再取消这个 CSS 属性。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用原生的拖拽 API 来实现排序功能更简单和易用，但目前手机浏览器还不支持这个功能。排序中的过渡动画是一个难点，特别是动画过程中移除事件的响应。如果可以使用 JS 的方式来临时禁用所有事件的响应，应该可以处理的更优雅。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/HTML_Drag_and_Drop_API\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTML Drag and Drop API</a></p>\\n<p><a href=\\"https://github.com/acgotaku/simple-drag-drop-sort-list\\" target=\\"_blank\\" rel=\\"noreferrer\\">simple-drag-drop-sort-list</a></p>\\n<p><a href=\\"https://aerotwist.com/blog/flip-your-animations/\\" target=\\"_blank\\" rel=\\"noreferrer\\">FLIP Your Animations</a></p>\\n<p><a href=\\"https://web.dev/drag-and-drop/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using the HTML5 Drag and Drop API</a></p>\\n"},{"title":"如何实现虚拟滚动条","url":"/posts/2022-05-12-virtual-scroll/","date":"2022-05-12 19:25","tags":["web"],"html":"<p>最近在做UI组件，发现下拉组件经常会有很多选项导致渲染的DOM过多，在低性能的设备上交互变的很卡。例如最常见的需求就是下拉选择所在国家或者地区，全世界有两百多个国家或者地区。\\n如果把所有国家或者地区都渲染出来必然会导致DOM过多，在低性能设备上滚动起来都会很卡。这时候就需要使用虚拟滚动条来提高渲染性能。</p>\\n<h2 id=\\"虚拟滚动条原理\\" tabindex=\\"-1\\">虚拟滚动条原理 <a class=\\"header-anchor\\" href=\\"#虚拟滚动条原理\\" aria-label=\\"Permalink to &quot;虚拟滚动条原理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>虚拟滚动的原理是显示的容器高度固定，我们只渲染用户看到的选项。但是选项容器的高度还是设置成所有选项的高度，这样滚动条效果保持一样，不过实际渲染的DOM数量却大大减少。</p>\\n<h2 id=\\"虚拟滚动条的数学计算\\" tabindex=\\"-1\\">虚拟滚动条的数学计算 <a class=\\"header-anchor\\" href=\\"#虚拟滚动条的数学计算\\" aria-label=\\"Permalink to &quot;虚拟滚动条的数学计算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前虚拟滚动的主要限制是需要知道显示容器的高度，渲染的每个选项的高度以及渲染的选项的数量。我们可以通过用户的滚动距离来计算需要显示的内容以及需要偏移的距离。</p>\\n<p>细节请参考下面的代码：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> VirtualScroll</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IVirtualScrollProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  itemCount, </span><span style=\\"color:#6A737D\\">// 选项的数量</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  height, </span><span style=\\"color:#6A737D\\">// 显示容器的高度</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  childHeight, </span><span style=\\"color:#6A737D\\">// 选项的高度</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  itemData </span><span style=\\"color:#6A737D\\">// 选项元素</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> wrapperRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLDivElement</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 得高容器滚动了多少距离</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollTop</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useScrollAware</span><span style=\\"color:#24292E\\">(wrapperRef);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 计算渲染的选项的总高度</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> totalHeight</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> childHeight </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> itemCount,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [childHeight, itemCount]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 根据滚动距离，计算要渲染的选项的起始位置</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> startIndex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> Math.</span><span style=\\"color:#6F42C1\\">floor</span><span style=\\"color:#24292E\\">(scrollTop </span><span style=\\"color:#D73A49\\">/</span><span style=\\"color:#24292E\\"> childHeight),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [scrollTop, childHeight]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 根据容器的高度计算要渲染的选项的数量</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> visibleItemCount</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> Math.</span><span style=\\"color:#6F42C1\\">ceil</span><span style=\\"color:#24292E\\">(height </span><span style=\\"color:#D73A49\\">/</span><span style=\\"color:#24292E\\"> childHeight),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [height, childHeight]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 根据渲染的选项的起始位置，计算选项的偏移量</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> offsetY</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> startIndex </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> childHeight,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [childHeight, startIndex]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 计算实际显示的选项元素</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> visibleItemData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> itemData.</span><span style=\\"color:#6F42C1\\">slice</span><span style=\\"color:#24292E\\">(startIndex, startIndex </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#24292E\\"> visibleItemCount);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [itemData, startIndex, visibleItemCount]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">div</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        height,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        overflow: </span><span style=\\"color:#032F62\\">'auto'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{wrapperRef}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          position: </span><span style=\\"color:#032F62\\">'relative'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          overflow: </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          willChange: </span><span style=\\"color:#032F62\\">'transform'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          height: totalHeight</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#22863A\\">div</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            willChange: </span><span style=\\"color:#032F62\\">'transform'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            transform: </span><span style=\\"color:#032F62\\">\`translate3d(0, \${</span><span style=\\"color:#24292E\\">offsetY</span><span style=\\"color:#032F62\\">}px, 0)\`</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          {visibleItemData}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> default</span><span style=\\"color:#6F42C1\\"> memo</span><span style=\\"color:#24292E\\">(VirtualScroll);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br><span class=\\"line-number\\">62</span><br><span class=\\"line-number\\">63</span><br><span class=\\"line-number\\">64</span><br></div></div><p>完整的实现请参考 <a href=\\"https://github.com/acgotaku/simple-ui/blob/master/src/components/Select/VirtualRow.tsx\\" target=\\"_blank\\" rel=\\"noreferrer\\">Simple UI - Select</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在知道虚拟滚动条的原理之后，发现并不难实现，重点要理解几个数值的计算，才能明白为什么这样能达到预期的效果。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://dev.to/adamklein/build-your-own-virtual-scroll-part-i-11ib\\" target=\\"_blank\\" rel=\\"noreferrer\\">Build your Own Virtual Scroll</a></p>\\n"},{"title":"禁用页面滚动","url":"/posts/2022-03-13-scroll-lock/","date":"2022-03-13 15:11","tags":["web"],"html":"<p>在设计组件的时候，例如 Modal 弹窗组件，在显示组件的时候我们不希望页面可以滚动。这时候就需要临时禁用页面的滚动功能。接下来就讲解下禁用页面滚动的方法。</p>\\n<h2 id=\\"禁用滚动\\" tabindex=\\"-1\\">禁用滚动 <a class=\\"header-anchor\\" href=\\"#禁用滚动\\" aria-label=\\"Permalink to &quot;禁用滚动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>禁用滚动的方法很简单，只需要在页面的 body 元素上设置 overflow 属性为 hidden，就可以禁用页面的滚动了。但是我们需要考虑到，如果我们的页面有滚动条，滚动条的消失会影响页面的显示效果。\\n所以完美的禁用滚动方式需要考虑到当前页面滚动条的宽度。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> getScrollbarWidth</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollbarWidth</span><span style=\\"color:#D73A49\\"> =</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    window.innerWidth </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> document.documentElement.clientWidth;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> scrollbarWidth;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> lockBody</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollbarWidth</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> getScrollbarWidth</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scrollbarWidth) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'padding-right'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">\`\${</span><span style=\\"color:#24292E\\">scrollbarWidth</span><span style=\\"color:#032F62\\">}px\`</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br></div></div><p>为了保证不影响页面的显示效果，我们需要计算出当前页面滚动条的宽度，然后设置 body 的 padding-right 属性，这样就可以保证页面的显示效果。</p>\\n<h2 id=\\"恢复滚动\\" tabindex=\\"-1\\">恢复滚动 <a class=\\"header-anchor\\" href=\\"#恢复滚动\\" aria-label=\\"Permalink to &quot;恢复滚动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> unlockBody</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">removeProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">removeProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'padding-right'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>恢复滚动只需要把添加到 CSS 属性删除即可。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果一直使用 Mac 的触摸板来编程的话，有时候很难意识到滚动条的存在，但是对于大多数的 Windows 用户来说，滚动条会一直存在的。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/mantinedev/mantine/blob/master/src/mantine-hooks/src/use-scroll-lock/use-scroll-lock.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">use-scroll-lock.ts</a></p>\\n"}]},"relativePath":"tags/web/page/2/index.md","filePath":"tags/[slug].md"}`),l={name:"tags/web/page/2/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const u=s(l,[["render",p]]);export{b as __pageData,u as default};
